import difflib, hashlib, json
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlsplit
class Links(HTMLParser):
    def __init__(self, raw):
        super().__init__()
        self.links = []
        self.feed(raw.decode('utf-8'))
    def handle_starttag(self, tag, attrs):
        href = dict(attrs).get('href')
        if tag == 'a' and href:
            url = urlsplit(href)
            self.links.append({'kind': 'mailto', 'subject': parse_qs(url.query).get('subject', [])} if url.scheme == 'mailto' else {'kind': 'link', 'href': href})
paths = {'served': 'products/distribution/catalogue-editor-example-placement/placement-live-readback.html', 'baseline': 'products/distribution/catalogue-editor-example-placement/live-baseline.html', 'offline_preview': 'products/distribution/catalogue-example-baseline-reconciliation/offline-preview/index-preview.html', 'current_candidate': 'products/sites/shopify-catalogue-example/index.html'}
raw = {key: Path(path).read_bytes() for key, path in paths.items()}
served = raw['served']
served_links = Links(served).links
results = {}
for key, data in raw.items():
    links = Links(data).links
    diff = list(difflib.unified_diff(served.decode().splitlines(), data.decode().splitlines(), fromfile='served', tofile=key, n=1))
    results[key] = {'path': paths[key], 'sha256': hashlib.sha256(data).hexdigest(), 'bytes_equal_to_served': data == served, 'links_equal_to_served': links == served_links, 'mailto_subjects': [link['subject'] for link in links if link['kind'] == 'mailto'], 'diff_line_count': len(diff), 'diff_excerpt': '\n'.join(diff[:70])[:4500]}
output = Path('products/distribution/catalogue-editor-example-placement/placement-diagnostics.json')
output.write_text(json.dumps({'served_matches_fetch_receipt': results['served']['sha256'] == '8bb6898a489669b02cd4db20f10abbe524a2d87b4c4590d233b49d337eb83bcc', 'comparisons': results}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({key: {field: value for field, value in item.items() if field != 'diff_excerpt'} for key, item in results.items()}, ensure_ascii=False))
